});

/* 算法逻辑 */
function getResult(arr) {
  const count = {};
  const first = {};

  for (let i = 0; i < arr.length; i++) {
    const s = arr[i];

    if (count[s] == undefined) count[s] = 0;
    count[s]++;

    if (first[s] == undefined) first[s] = i;
  }

  return [...Object.keys(first)]
    .sort((a, b) =>
      count[a] != count[b] ? count[b] - count[a] : first[a] - first[b]
    )
    .join(",");
}

